import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Static Analysis in the Era of Frontier AI: Why LLMs Need Deterministic Oracles","description":"A deep technical examination of where static application security testing stands against models like Claude Opus 5.5 and Gemini 3.8 Flash, and why autonomous AI coding agents require compiler-mode deterministic verifiers like Frensense.","frontmatter":{"written-against-version":"0.7.0","fact-checked":"2026-10-24","source-revision":"8a0ef9d-dirty","title":"Static Analysis in the Era of Frontier AI: Why LLMs Need Deterministic Oracles","date":"2026-10-09T00:00:00.000Z","image":"/covers/frontier-ai-sast.svg","description":"A deep technical examination of where static application security testing stands against models like Claude Opus 5.5 and Gemini 3.8 Flash, and why autonomous AI coding agents require compiler-mode deterministic verifiers like Frensense.","head":[["meta",{"property":"og:title","content":"Static Analysis in the Era of Frontier AI: Why LLMs Need Deterministic Oracles"}],["meta",{"property":"og:description","content":"A deep technical examination of where static application security testing stands against models like Claude Opus 5.5 and Gemini 3.8 Flash, and why autonomous AI coding agents require compiler-mode deterministic verifiers like Frensense."}],["meta",{"property":"og:image","content":"https://frensense.friehub.cloud/covers/frontier-ai-sast.svg"}],["meta",{"name":"twitter:image","content":"https://frensense.friehub.cloud/covers/frontier-ai-sast.svg"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://frensense.friehub.cloud/blog/2026-10-09-static-analysis-in-the-age-of-frontier-ai"}],["meta",{"name":"twitter:title","content":"Static Analysis in the Era of Frontier AI: Why LLMs Need Deterministic Oracles"}],["meta",{"name":"twitter:description","content":"A deep technical examination of where static application security testing stands against models like Claude Opus 5.5 and Gemini 3.8 Flash, and why autonomous AI coding agents require compiler-mode deterministic verifiers like Frensense."}],["meta",{"name":"keywords","content":"static application security testing, SAST, LLM code security, Claude Opus 5.5, Gemini 3.8 Flash, Semgrep, CodeQL, Model Context Protocol, MCP, deterministic taint analysis, compiler security, Rust"}],["meta",{"property":"article:published_time","content":"2026-10-09T00:00:00Z"}],["meta",{"property":"article:modified_time","content":"2026-10-22T00:00:00Z"}],["script",{"type":"application/ld+json"},"{\\n  \\"@context\\": \\"https://schema.org\\",\\n  \\"@type\\": \\"TechArticle\\",\\n  \\"headline\\": \\"Static Analysis in the Era of Frontier AI: Why LLMs Need Deterministic Oracles\\",\\n  \\"description\\": \\"A deep technical examination of where static application security testing stands against models like Claude Opus 5.5 and Gemini 3.8 Flash, and why autonomous AI coding agents require compiler-mode deterministic verifiers like Frensense.\\",\\n  \\"datePublished\\": \\"2026-10-09T00:00:00Z\\",\\n  \\"dateModified\\": \\"2026-10-22T00:00:00Z\\",\\n  \\"author\\": {\\n    \\"@type\\": \\"Organization\\",\\n    \\"name\\": \\"Friehub\\",\\n    \\"url\\": \\"https://friehub.cloud\\"\\n  },\\n  \\"publisher\\": {\\n    \\"@type\\": \\"Organization\\",\\n    \\"name\\": \\"Friehub\\",\\n    \\"url\\": \\"https://friehub.cloud\\"\\n  },\\n  \\"mainEntityOfPage\\": {\\n    \\"@type\\": \\"WebPage\\",\\n    \\"@id\\": \\"https://frensense.friehub.cloud/blog/2026-10-09-static-analysis-in-the-age-of-frontier-ai\\"\\n  },\\n  \\"keywords\\": [\\"static analysis\\", \\"SAST\\", \\"AI security\\", \\"Claude Opus 5.5\\", \\"Gemini 3.8 Flash\\", \\"MCP\\", \\"Rust\\"]\\n}\\n"],["link",{"rel":"canonical","href":"https://frensense.friehub.cloud/blog/2026-10-09-static-analysis-in-the-age-of-frontier-ai"}]]},"headers":[],"relativePath":"blog/2026-10-09-static-analysis-in-the-age-of-frontier-ai.md","filePath":"blog/2026-10-09-static-analysis-in-the-age-of-frontier-ai.md"}'),i={name:"blog/2026-10-09-static-analysis-in-the-age-of-frontier-ai.md"};function r(o,e,l,d,c,h){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="static-analysis-in-the-era-of-frontier-ai-why-llms-need-deterministic-oracles" tabindex="-1">Static Analysis in the Era of Frontier AI: Why LLMs Need Deterministic Oracles <a class="header-anchor" href="#static-analysis-in-the-era-of-frontier-ai-why-llms-need-deterministic-oracles" aria-label="Permalink to &quot;Static Analysis in the Era of Frontier AI: Why LLMs Need Deterministic Oracles&quot;">​</a></h1><blockquote><p><strong>Provenance.</strong> Written against Frensense 0.7.0; fact-checked on source rev <code>d6cfd3f</code> (0.8.0-beta). Mechanism references: <code>src/</code>, MCP tool surface (<code>frensense mcp</code>), baseline machinery in <code>docs/AGENT_INTEGRATION.md</code>.</p></blockquote><blockquote><p><strong>Where the numbers come from.</strong> Every accuracy figure in this post that is measured comes from the <strong>OWASP Benchmark for Python (v0.1)</strong> - 1,230 independently authored cases with an authoritative expected-results CSV, scanned engine-alone (no <code>.frc</code> bundle) with Frensense v0.7.0 on 2026-10-02: TPR 28.5%, FPR 2.3%, score (TPR - FPR) 26.2%. That run&#39;s per-CWE table - including the classes that score <strong>zero</strong> - is published in <code>docs/BENCHMARKING.md</code>, and you can reproduce it with <code>./scripts/reproduce_benchmark.sh</code>. Claims of a 0.0% false-positive rate in rule-bundle contexts refer to the <em>replay gate over a bundle&#39;s own corpus</em> (its twin examples and held-out variants), which is a different validator from the OWASP ground truth; we never conflate the two. Where a competitor number appears without our own measurement, we say so.</p></blockquote><p>With the arrival of frontier reasoning models such as Claude Opus 5.5, Gemini 3.8 Flash, Claude Fable, and GLM 5.3, the software engineering discipline is experiencing an unprecedented shift. Autonomous coding agents-integrated across environments like Claude Code, Cursor, Devin, and Antigravity-now generate thousands of lines of complex application code per hour.</p><p>Inevitably, this wave of AI capability prompted a recurring question across application security teams:</p><blockquote><p><em>If frontier language models can understand semantic context, reason over codebases, and synthesize bug fixes, is static application security testing (SAST) obsolete?</em></p></blockquote><p>The answer from empirical security research and production compiler engineering is unequivocal: <strong>No. In fact, frontier AI makes deterministic, compiler-mode static analysis more critical than at any point in computing history.</strong></p><p>To understand why, we must examine the boundary between <strong>probabilistic semantic reasoning</strong> and <strong>deterministic mathematical reachability</strong>, and why the future of secure software rests on a hybrid architecture.</p><hr><h2 id="_1-the-two-modalities-of-code-security" tabindex="-1">1. The Two Modalities of Code Security <a class="header-anchor" href="#_1-the-two-modalities-of-code-security" aria-label="Permalink to &quot;1. The Two Modalities of Code Security&quot;">​</a></h2><p>Modern application security requires solving two fundamentally different classes of problems:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+------------------------------------+------------------------------------+</span></span>
<span class="line"><span>|  PROBABILISTIC SEMANTIC REASONING  | DETERMINISTIC REACHABILITY PROOF  |</span></span>
<span class="line"><span>|         (Frontier AI Models)       |     (Compiler-Mode SAST / IR)      |</span></span>
<span class="line"><span>+------------------------------------+------------------------------------+</span></span>
<span class="line"><span>| • Business logic flaws (IDOR)      | • Taint propagation through memory |</span></span>
<span class="line"><span>| • Broken authentication workflows  | • Untrusted input reaching sinks   |</span></span>
<span class="line"><span>| • Price and parameter tampering    | • Control-flow guard validation    |</span></span>
<span class="line"><span>| • Remediation &amp; patch generation   | • Deterministic repeat; explicit Unknown verdicts |</span></span>
<span class="line"><span>+------------------------------------+------------------------------------+</span></span></code></pre></div><h3 id="what-frontier-llms-excel-at" tabindex="-1">What Frontier LLMs Excel At <a class="header-anchor" href="#what-frontier-llms-excel-at" aria-label="Permalink to &quot;What Frontier LLMs Excel At&quot;">​</a></h3><p>Frontier models possess a capability traditional static analyzers never had: <strong>semantic comprehension of business intent</strong>.</p><ul><li>An LLM can inspect an e-commerce checkout handler and understand that charging a user an unchecked amount from <code>req.body.price</code> violates domain intent, even if the dataflow is technically well-formed.</li><li>LLMs identify Broken Object Level Authorization (IDOR), architectural race conditions, and workflow bypasses that lack any syntactic taint signature.</li><li>Once a flaw is located, models like Claude Opus 5.5 and Gemini 3.8 Flash synthesize idiomatic, contextual pull requests that resolve the issue while preserving API contracts.</li></ul><h3 id="the-inherent-failure-modes-of-pure-llm-audits" tabindex="-1">The Inherent Failure Modes of Pure LLM Audits <a class="header-anchor" href="#the-inherent-failure-modes-of-pure-llm-audits" aria-label="Permalink to &quot;The Inherent Failure Modes of Pure LLM Audits&quot;">​</a></h3><p>Despite remarkable reasoning leaps, deploying LLMs as standalone security scanners in production pipelines breaks down against three hard barriers:</p><ol><li><strong>The Determinism Requirement</strong>: CI/CD security gates must be mathematically deterministic. If commit <code>SHA-A</code> passes a security audit at 9:00 AM, it must pass at 9:00 PM. Frontier LLMs remain probabilistic; identical prompts on identical files can produce divergent vulnerability classifications or severity scores across runs.</li><li><strong>The &quot;Inner Loop&quot; Latency Barrier</strong>: A developer writing code in their editor, or committing via a pre-commit hook, requires sub-100 millisecond feedback. Querying a cloud frontier model entails multi-second Time-to-First-Token (TTFT) and token generation latency. Compilers and SSA dataflow traversals execute locally in single-digit milliseconds.</li><li><strong>The Hallucination of Reachability</strong>: Frontier models routinely hallucinate taint reachability. An LLM may inspect five nested functions, observe a sanitization method, and conclude the path is neutralized-overlooking pointer aliasing, closure capture, or branch-infeasible conditions a formal Control Flow Graph (CFG) evaluates mechanically. The engine&#39;s counterside is equally explicit: when a call or variable cannot be resolved during its demand-driven analysis, it reports <strong>Unknown</strong> rather than guessing clean - an honest answer that probabilistic recall over an unexecuted mental model does not have.</li><li><strong>Token Economics at Monorepo Scale</strong>: Full-repo security scans on 2-million-line monorepos via frontier reasoning APIs cost significant token expenditure per run and encounter strict enterprise rate limits.</li></ol><hr><h2 id="_2-the-sast-landscape-in-2026-codeql-semgrep-and-frensense" tabindex="-1">2. The SAST Landscape in 2026: CodeQL, Semgrep, and Frensense <a class="header-anchor" href="#_2-the-sast-landscape-in-2026-codeql-semgrep-and-frensense" aria-label="Permalink to &quot;2. The SAST Landscape in 2026: CodeQL, Semgrep, and Frensense&quot;">​</a></h2><p>To see where Frensense stands, we must first be honest about the incumbents: <strong>CodeQL and Semgrep Pro are more mature, deeper tools, and we will not pretend otherwise.</strong> What follows is a grounded comparison, not a sales chart.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Dimension</th><th style="text-align:left;">Semgrep CE / Pro</th><th style="text-align:left;">GitHub CodeQL</th><th style="text-align:left;">Frensense</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Analysis Paradigm</strong></td><td style="text-align:left;">CE: intraprocedural AST patterns; <strong>Pro: proprietary cross-file + cross-function dataflow</strong></td><td style="text-align:left;">Relational semantic database (Datalog-style queries)</td><td style="text-align:left;">SSA-lowered CFG, demand-driven backward dataflow</td></tr><tr><td style="text-align:left;"><strong>Build Requirement</strong></td><td style="text-align:left;">Zero</td><td style="text-align:left;"><strong>Zero for most languages today</strong>: default setup creates the database without a build for C/C++, C#, Java, and Rust (<code>none</code> build mode); autobuild/manual modes increase accuracy further</td><td style="text-align:left;">Zero</td></tr><tr><td style="text-align:left;"><strong>Analysis Depth</strong></td><td style="text-align:left;">Pro covers cross-file taint, constant propagation, type inference</td><td style="text-align:left;"><strong>The industry gold standard for interprocedural depth</strong></td><td style="text-align:left;">Interprocedural backward taint; narrower in practice (see our limits, below)</td></tr><tr><td style="text-align:left;"><strong>False Positives</strong></td><td style="text-align:left;">Pro rules use curated taint configs to reduce noise; the vendor&#39;s own figures report ~25% fewer FPs and ~250% more true positives under cross-file analysis (unaudited vendor numbers)</td><td style="text-align:left;">Tuned query suites with years of production refinement</td><td style="text-align:left;">2.3% FPR on the OWASP Benchmark Python run (measured, independently authored ground truth); 0.0% within a bundle&#39;s own replay corpus</td></tr><tr><td style="text-align:left;"><strong>Rule Distribution</strong></td><td style="text-align:left;">YAML rules, huge community registry</td><td style="text-align:left;">QL queries, deeply human-reviewed</td><td style="text-align:left;">Compiled binary bundles (<code>.frc</code>), mechanically replay-verified</td></tr><tr><td style="text-align:left;"><strong>Language Coverage</strong></td><td style="text-align:left;">30+ languages</td><td style="text-align:left;">~15 languages with very deep grammars</td><td style="text-align:left;">6 languages (TS, JS, Python, Go, Rust, C)</td></tr><tr><td style="text-align:left;"><strong>AI Integration</strong></td><td style="text-align:left;">Cloud AI triage add-on</td><td style="text-align:left;">Copilot autofix + code scanning</td><td style="text-align:left;">Native MCP server in the same binary</td></tr></tbody></table><h3 id="what-codeql-and-semgrep-do-better-than-us" tabindex="-1">What CodeQL and Semgrep do better than us <a class="header-anchor" href="#what-codeql-and-semgrep-do-better-than-us" aria-label="Permalink to &quot;What CodeQL and Semgrep do better than us&quot;">​</a></h3><p>An honest accounting, sourced from what their tooling does today:</p><ul><li><strong>Depth and maturity.</strong> CodeQL&#39;s interprocedural analysis and curated query libraries have a decade of refinement Frensense does not have. Semgrep&#39;s Pro Engine performs cross-file taint tracking Frensense&#39;s per-file demand engine cannot match when flows leave a file.</li><li><strong>Ecosystem breadth.</strong> More languages, community rule registries, and integrations we do not ship.</li><li><strong>Sustained security teams.</strong> Their rules are maintained continuously by dedicated research teams; ours are grown from corpus - transparent, but narrower per release.</li></ul><h3 id="where-frensense-s-architecture-differs-not-beats" tabindex="-1">Where Frensense&#39;s architecture differs (not &quot;beats&quot;) <a class="header-anchor" href="#where-frensense-s-architecture-differs-not-beats" aria-label="Permalink to &quot;Where Frensense&#39;s architecture differs (not &quot;beats&quot;)&quot;">​</a></h3><p>The honest differences are <em>design choices</em>, not superiority:</p><ul><li><strong>Latency budget for agent loops.</strong> Frensense&#39;s demand-driven backward analysis is deliberately scoped for millisecond-scale, per-edit verification (<code>frensense_diff</code> over an MCP session) rather than whole-program exhaustive computation. CodeQL trades the same latency for comprehensiveness - a defensible choice, and for whole-repo scheduled analysis, usually the better one.</li><li><strong>Mechanical knowledge validation.</strong> A <code>.frc</code> fact ships only if the replay gate proves it separates its positive/negative corpus. CodeQL queries and Semgrep rules do not require themselves to pass a machine check; validation there is human review and CI tuning. This bounds our rule-writing throughput - a bundle cannot be wider than what twins prove - in exchange for measurable guarantees.</li></ul><h3 id="the-semgrep-landscape-ce-vs-pro-engine" tabindex="-1">The Semgrep Landscape: CE vs Pro Engine <a class="header-anchor" href="#the-semgrep-landscape-ce-vs-pro-engine" aria-label="Permalink to &quot;The Semgrep Landscape: CE vs Pro Engine&quot;">​</a></h3><p>Semgrep Community Edition documents itself as intraprocedural-only: it does not track dataflow across files unless run with the <strong>Pro Engine</strong> (a proprietary binary installed additionally). Pro&#39;s cross-file analysis is real and strong; the honest note is that it is not open source, and community rules (the free pack) are pattern rules without interprocedural dataflow at all.</p><h3 id="the-codeql-dilemma-depth-with-real-setup-costs" tabindex="-1">The CodeQL Dilemma: Depth with Real Setup Costs <a class="header-anchor" href="#the-codeql-dilemma-depth-with-real-setup-costs" aria-label="Permalink to &quot;The CodeQL Dilemma: Depth with Real Setup Costs&quot;">​</a></h3><p>GitHub CodeQL represents the gold standard of semantic relational analysis, and its <code>none</code> build mode has removed most of the historical setup friction for C/C++, C#, Java, and Rust. What remains true is that CodeQL works best when a codebase can be correctly extracted (Kotlin and some compiled scenarios still need builds; no-build extraction for compiled languages <em>may produce less accurate results</em> than build-based extraction, per GitHub&#39;s own documentation), and full database construction plus query execution runs on a timescale of minutes per repository. That is an appropriate, deliberate trade for scheduled whole-repo analysis - it is simply a different latency class from an editor-loop verifier.</p><h3 id="the-frensense-architecture-a-different-point-in-the-design-space" tabindex="-1">The Frensense Architecture: A Different Point in the Design Space <a class="header-anchor" href="#the-frensense-architecture-a-different-point-in-the-design-space" aria-label="Permalink to &quot;The Frensense Architecture: A Different Point in the Design Space&quot;">​</a></h3><p>Frensense was built for the fast, deterministic verification niche rather than to displace the incumbents:</p><ul><li><strong>Zero Build Interception</strong>: Frensense parses raw source directly via tree-sitter - no database construction step, no build environment (CodeQL&#39;s modern no-build modes close much of the historical gap here; credit where due).</li><li><strong>Demand-driven for agent latency</strong>: analysis is seeded at sinks and walks backward, trading exhaustive whole-program recall for millisecond-scale, IDE/agent-loop feedback with explicit <strong>Unknown</strong> verdicts when it cannot prove.</li><li><strong>Replay-verified knowledge</strong>: <code>.frc</code> facts must separate their positive/negative corpus before shipping - a validation CodeQL queries and Semgrep rules do not require of themselves - at the cost of narrower per-release coverage than incumbent curated libraries.</li></ul><hr><h2 id="_3-the-autonomous-agent-dilemma-who-audits-the-auditor" tabindex="-1">3. The Autonomous Agent Dilemma: Who Audits the Auditor? <a class="header-anchor" href="#_3-the-autonomous-agent-dilemma-who-audits-the-auditor" aria-label="Permalink to &quot;3. The Autonomous Agent Dilemma: Who Audits the Auditor?&quot;">​</a></h2><p>The most critical development in modern software engineering is the rise of autonomous coding agents. When models like Claude Opus 5.5, Gemini 3.8 Flash, or GLM 5.3 write production code, who verifies their security?</p><p>If an agent inspects its own generated code and asks: <em>&quot;Is this safe?&quot;</em>, it exhibits self-referential confirmation bias. LLMs frequently reinforce their own oversights.</p><p>Furthermore, benchmarks evaluating AI-generated code (such as Meta&#39;s <strong>CyberSecEval</strong>) evaluate LLM outputs by running static analyzers like CodeQL and Semgrep against them. Static analysis remains the objective ground truth.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-------------------+        1. Generate Patch        +-------------------+</span></span>
<span class="line"><span>|                   | ------------------------------&gt; |                   |</span></span>
<span class="line"><span>|  Frontier Agent   |                                 |   Target Code     |</span></span>
<span class="line"><span>| (Opus 5.5 / 3.8)  | &lt;------------------------------ |                   |</span></span>
<span class="line"><span>|                   |    3. Precise Taint Trace (ms)  | +-----------------+</span></span>
<span class="line"><span>+-------------------+                                           |</span></span>
<span class="line"><span>          |                                                     | 2. Scan</span></span>
<span class="line"><span>          | JSON-RPC (MCP)                                      v</span></span>
<span class="line"><span>          +--------------------------------------------&gt; +-------------------+</span></span>
<span class="line"><span>                                                         |   Frensense MCP   |</span></span>
<span class="line"><span>                                                         |  (.frc Bundles)   |</span></span>
<span class="line"><span>                                                         +-------------------+</span></span></code></pre></div><h3 id="frensense-as-the-native-agentic-oracle" tabindex="-1">Frensense as the Native Agentic Oracle <a class="header-anchor" href="#frensense-as-the-native-agentic-oracle" aria-label="Permalink to &quot;Frensense as the Native Agentic Oracle&quot;">​</a></h3><p>Frensense embeds a native Model Context Protocol (MCP) server directly into its unified binary:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frensense</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span></span></code></pre></div><p>Through MCP, any AI coding assistant has immediate access to deterministic verification tools:</p><ul><li><code>frensense_scan_file</code>: Instant module analysis with zero startup overhead.</li><li><code>frensense_diff</code>: Evaluates a prospective git patch in memory before it is written to disk.</li><li><code>frensense_audit</code>: Full repository verification.</li></ul><p>When an AI agent modifies code, it invokes <code>frensense_diff</code> via MCP and receives an objective, mechanically recomputed answer on whether a new dataflow path reaches an unvalidated sink - in milliseconds, measured in the engine&#39;s own local run rather than a marketing figure. If a flaw exists, the agent receives an exact taint trace, patches the vulnerability, and verifies the resolution against the same stable finding ID before submitting the pull request.</p><hr><h2 id="_4-the-future-a-tiered-hybrid-security-architecture" tabindex="-1">4. The Future: A Tiered Hybrid Security Architecture <a class="header-anchor" href="#_4-the-future-a-tiered-hybrid-security-architecture" aria-label="Permalink to &quot;4. The Future: A Tiered Hybrid Security Architecture&quot;">​</a></h2><p>The software security industry is converging on a tiered model that pairs deterministic speed with frontier reasoning:</p><ol><li><strong>Tier 1 - Deterministic Verification (Frensense)</strong>: <ul><li>Runs locally in editor LSPs, pre-commit hooks, CI gates, and AI agent loops via MCP.</li><li>Catches standard injection vulnerabilities (SQLi, SSRF, Command Injection, Memory Safety, Path Traversal) with a measured 2.3% false-positive rate on the OWASP Benchmark Python run - not zero, and we publish the per-class numbers including the classes we miss (see <code>docs/BENCHMARKING.md</code>).</li></ul></li><li><strong>Tier 2 - Semantic &amp; Business Logic Triage (Frontier AI)</strong>: <ul><li>Operates on pull requests and release candidates.</li><li>Evaluates domain-level authorization logic (IDOR, role boundaries, business workflows).</li><li>Ingests Frensense&#39;s deterministic findings and automatically drafts contextual pull requests to remediate flaws.</li></ul></li></ol><p>By separating deterministic dataflow verification from probabilistic semantic reasoning, engineering teams achieve both instant developer feedback and complete threat coverage.</p><hr><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><p>To install the latest Frensense engine:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Rust / Cargo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frensense</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Node.js / NPM (Global CLI)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @friehub/frensense</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Instant Runner (Zero Install)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @friehub/frensense</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>To explore verified rule bundles and inspect our differential capability matrices, visit the <a href="/bundles">Frensense Bundles Portal</a> or consult our <a href="/guide/getting-started">Getting Started Guide</a>.</p>`,57)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
